SELECT "investor_name" AS "investor_name", "issuer_name" AS "issuer_name", "pricing_ts" AS "pricing_date", "deal_name" AS "deal_name", "tenors" AS "tenors", "tranche_name" AS "tranche_name", "order_demand_qty" AS "order_demand_qty", "order_allocation" AS "order_allocation", "currency" AS "currency", COUNT("order_id") AS "row_count" FROM "bds_dg_oraas"."dgstream"."vw_order_detail" WHERE "product" = __P_f0__ AND UPPER("investor_name") LIKE UPPER(__P_f1__) AND "pricing_ts" >= __P_f2__ AND "pricing_ts" < __P_f3__ GROUP BY "investor_name", "issuer_name", "pricing_ts", "deal_name", "tenors", "tranche_name", "order_demand_qty", "order_allocation", "currency" ORDER BY "issuer_name" ASC, "pricing_date" DESC LIMIT 200
